CALENDARS = {"FOMC": FOMC, "EMPLOYMENT": EMPLOYMENT, "CPI": CPI, "PPI": PPI}
RELEASE_TIME_ET = {"FOMC": "14:00", "EMPLOYMENT": "08:30", "CPI": "08:30", "PPI": "08:30"}


def announcement_days(kinds=("FOMC", "EMPLOYMENT", "CPI", "PPI")) -> pd.DatetimeIndex:
    """Union of release days for the given kinds, as tz-naive normalized dates."""
    if isinstance(kinds, str):
        kinds = [kinds]
    days = set()
    for k in kinds:
        days.update(pd.Timestamp(d) for d in CALENDARS[k.upper()])
    return pd.DatetimeIndex(sorted(days))


def kinds_on(day) -> list[str]:
    """Which release kinds fall on `day`."""
    d = pd.Timestamp(day).normalize().isoformat()[:10]
    return [k for k, ds in CALENDARS.items() if d in ds]
